function CardProgressionCommonEquipmentListNode:InitFilerNodeData()
    ---@type UICommonFilterMB
    local nodeEnv = CfUtils.GetLuaScr(self.FilterNode.gameObject, "Game.Behaviours.UICommonFilterMB")
    if nodeEnv == nil then return end
    nodeEnv:SetDefGroups(self:InitDefGroups())
    nodeEnv:SetFilterClass(Constants.UIFilterType.Equip)
    nodeEnv:SetStyleType(2)
end

function CardProgressionCommonEquipmentListNode:InitDefGroups()
    local screenList = cardConfMgr:GetAllScreenVo(Constants.UIFilterType.Equip)
    local groups = {}
    ---@param v ScreenVo
    for i, v in ipairs(screenList) do
         if v.id == Constants.EquipFilterType.Other then
             groups[v.id] = groups[v.id] or {}
             ---@param cond number
             for _, cond in pairs(v.condition) do
                 table.insert(groups[v.id], checkNumber(cond))
             end
             break
         end
    end
    return groups
 end

 ---InitBackpackDataList
---初始化背包数据列表
function CardProgressionCommonEquipmentListNode:InitBackpackDataList()
    local part       = Base.GetPart(self)
    local filterType = Base.GetFilterType(self)
    local t = {}
    if filterType == FilTerType.SUIT then
        Base.RefreshSuitDataPartList(self)
        t = part == 0 and Base.GetAllSuitDataPartListData(self) or Base.GetSuitDataPartListData(self)
    else
        --- part -1:核心, > 0 准备散件
        if part > 0 then
            ---初始化 装备数据库id ：装备数据库id
            local equipIdList = Base.GetEquipIdList(self)
            local equipId2EquipId = {}
            for i, v in pairs(equipIdList) do
                if checkNumber(v) > 0 then
                    equipId2EquipId[tostring(v)] = v
                end
            end
            --- 调用父类方法
            Base.InitEquipData(self, t, function(equipDojo, equipPart)
                --- 排除已装备的
                --return not equipId2EquipId[tostring(equipDojo.id)] and part == equipPart
                return part == equipPart
            end)

        elseif part == 0 then
            ---初始化 装备数据库id ：装备数据库id
            local equipIdList = Base.GetEquipIdList(self)
            local equipId2EquipId = {}
            for i, v in pairs(equipIdList) do
                if checkNumber(v) > 0 then
                    equipId2EquipId[tostring(v)] = v
                end
            end
            --- 调用父类方法
            Base.InitEquipData(self, t, function(equipDojo, equipPart)
                --- 排除已装备的
                -- print(table.dump(equipDojo))
                --return not equipId2EquipId[tostring(equipDojo.id)]
                --return checkInt(equipDojo.playerCardId) == 0
                return true
            end)
        end
    end

    self:RefreshFilterNode(t)
end

---InitSuitDataPartList
---初始化套装位置数据列表
---@param ownEquipPartMap table<number, table> table<装备的位置, 在该位置上拥有的装备列表>
function CardProgressionCommonEquipmentListNode:InitSuitDataPartList(ownEquipPartMap)
    local suitDataPartList = {}

    ----------------------------------------
    --- 初始化套装 装备 位置数据
    local equipIdList = Base.GetEquipIdList(self) or {}
    local playerEquip2playerEquipId = {}
    for i, equipId in ipairs(equipIdList) do
        if checkNumber(equipId) > 0 then
            playerEquip2playerEquipId[tostring(equipId)] = equipId
        end
    end

    Base.InitSuitEquipPartData(self, suitDataPartList, ownEquipPartMap, function(equipDojo, equipVo)
        --- 排除自己身上已装备的
        --return not playerEquip2playerEquipId[equipDojo.id]
        return true
    end)
    ----------------------------------------

    return suitDataPartList
end
